/* Advanced Jurassic Chronometer & Bio-Incubator Animation Engine */

/* 1. Flowing Molten Plasma Beam */
@keyframes plasmaFlow {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

.plasma-energy-bar {
  background: linear-gradient(
    90deg,
    #92400e 0%,
    #d97706 20%,
    #f59e0b 40%,
    #fef08a 50%,
    #f59e0b 60%,
    #d97706 80%,
    #92400e 100%
  );
  background-size: 200% 100%;
  animation: plasmaFlow 3s linear infinite;
  box-shadow: 0 0 16px rgba(245, 158, 11, 0.5), inset 0 0 8px rgba(254, 240, 138, 0.6);
}

.plasma-energy-bar.paused {
  animation-play-state: paused;
  filter: saturate(0.7) brightness(0.85);
}

