@keyframes chronoDialSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes chronoDialSpinReverse {
  from {
    transform: rotate(360deg);
  }
  to {
    transform: rotate(0deg);
  }
}

.chrono-dial-outer {
  transform-origin: center center;
  animation: chronoDialSpin 40s linear infinite;
}

.chrono-dial-outer.running {
  animation: chronoDialSpin 25s linear infinite;

