const { spawn } = require('child_process');
const http = require('http');

async function runSweep() {
  const edgePath = 'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
  const port = 9222;
  const proc = spawn(edgePath, [
    '--headless=new',
    `--remote-debugging-port=${port}`,
    '--disable-gpu',
    '--no-first-run',
    'http://localhost:5173/dino-pomodoro'
  ], { detached: false });

  await new Promise(r => setTimeout(r, 2000));

  try {
    const listData = await new Promise((resolve, reject) => {
      http.get(`http://localhost:${port}/json`, res => {
        let raw = '';
        res.on('data', chunk => raw += chunk);
        res.on('end', () => resolve(JSON.parse(raw)));
      }).on('error', reject);
    });

    const page = listData.find(t => t.type === 'page') || listData[0];
    if (!page || !page.webSocketDebuggerUrl) {
      throw new Error('No page target found');
    }

    const ws = new WebSocket(page.webSocketDebuggerUrl);
    const consoleLogs = [];
    const errors = [];

    await new Promise((resolve, reject) => {
      ws.onopen = resolve;
      ws.onerror = reject;
    });

    let msgId = 1;
    const send = (method, params = {}) => {
      const id = msgId++;
      ws.send(JSON.stringify({ id, method, params }));
      return id;
    };

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.method === 'Runtime.consoleAPICalled') {
        const text = msg.params.args.map(a => a.value || a.description || '').join(' ');
        consoleLogs.push({ type: msg.params.type, text });
        if (msg.params.type === 'error') {
          errors.push(text);
        }
      } else if (msg.method === 'Runtime.exceptionThrown') {
        const desc = msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails.text;
        errors.push(desc);
      }
    };

    send('Console.enable');
    send('Runtime.enable');
    send('Page.enable');

    // Wait 3.5s for React render and data sync
    await new Promise(r => setTimeout(r, 3500));

    // Inspect DOM for the EvoQuoteBanner
    const evalId = send('Runtime.evaluate', {
      expression: `(() => {
        const quoteEl = document.querySelector('blockquote');
        const quoteText = quoteEl ? quoteEl.textContent : null;
        const banner = document.querySelector('.group');
        const dinoName = document.querySelector('h2')?.textContent;
        return JSON.stringify({
          dinoName,
          hasQuoteBlock: !!quoteEl,
          quoteText,
          hasBanner: !!banner
        });
      })()`,
      returnByValue: true
    });

    const domResult = await new Promise(resolve => {
      const handler = (event) => {
        const msg = JSON.parse(event.data);
        if (msg.id === evalId) {
          ws.removeEventListener('message', handler);
          resolve(JSON.parse(msg.result?.result?.value || '{}'));
        }
      };
      ws.addEventListener('message', handler);
    });

    ws.close();
    proc.kill('SIGKILL');

    console.log('--- SWEEP REPORT ---');
    console.log('DOM Result:', domResult);
    console.log('Console Logs Captured:', consoleLogs.length);
    console.log('Runtime Errors:', errors);
    if (errors.length > 0) {
      process.exit(1);
    } else {
      console.log('SWEEP VERIFICATION: PASSED (ZERO RUNTIME ERRORS)');
      process.exit(0);
    }
  } catch (err) {
