      {/* Big Dynamic Countdown with 1Hz Heartbeat Pulse */}
      <div
        className={`font-mono text-4xl sm:text-5xl font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-[#fff1cc] to-[#f59e0b] tracking-tight drop-shadow-[0_4px_16px_rgba(0,0,0,0.9)] ${
          isRunning ? 'timer-digits-pulse' : ''
        }`}
      >
        {rutGonTime(timeRemaining, 'seconds')}
      </div>

      {/* Dynamic Charge Percentage */}
      <div className="text-[10.5px] font-mono font-bold text-amber-300/90 tracking-wider mt-0.5">
        {progressPercent.toFixed(1)}% CHARGED
      </div>
    </div>
  </div>

  {/* Molten Plasma Energy Conduit Track */}
  <div className="w-full space-y-1.5 mt-2">
    <div className="relative w-full h-3.5 bg-[#0e0a16] border border-[#3b2a52] rounded-full p-0.5 overflow-hidden shadow-inner">
      {/* Internal Reactor Tick Division Markers */}
      <div className="absolute inset-0 flex justify-between px-[25%] pointer-events-none z-10 opacity-30">
        <div className="w-[1px] h-full bg-white" />
        <div className="w-[1px] h-full bg-white" />
      </div>

      {/* Flowing Molten Plasma Fill Bar */}
      <div
        className={`plasma-energy-bar h-full rounded-full transition-all duration-1000 ease-linear relative ${
          isRunning ? '' : 'paused'
        }`}
        style={{ width: `${progressPercent}%` }}
      >
        {/* Leading Radiant Star Flare */}
        {progressPercent > 2 && progressPercent < 99 && (
          <div className="progress-head-flare absolute right-0 top-1/2 w-3.5 h-3.5 rounded-full bg-white pointer-events-none" />
        )}
      </div>
    </div>

    {/* Tri-Telemetry Status Strip */}
    <div className="flex items-center justify-between text-[10.5px] font-mono text-[#8c7a9e] px-1">
      <span className="flex items-center gap-1 text-emerald-400 font-bold" title="Elapsed Time">
        <span>⚡</span>
        <span>{rutGonTime(Math.max(0, sessionDuration - timeRemaining), 'seconds')}</span>
      </span>
      <span className="font-cinzel text-amber-400 font-bold uppercase tracking-wider text-[9.5px]">
        {isComplete ? '100% COMPLETE' : `${progressPercent.toFixed(0)}% INCUBATED`}
      </span>
